def interview_questions(mode: str, topic: str | None, difficulty: str, skills: list[str], count: int = 5, projects: list[str] | None = None):
    pool = [q for q in BANK if q["difficulty"] == difficulty]
    if not pool: pool = BANK[:]
    if mode == "resume":
        personalized = [{"id":f"resume-{skill.lower().replace(' ','-')}","topic":"Resume","difficulty":difficulty,"prompt":f"Your resume mentions {skill}. Describe a specific time you used it, the challenge, your decisions, and the outcome.","reference":f"A strong response should explain context, specific use of {skill}, a decision or challenge, and a concrete outcome.","concepts":["context",skill.lower(),"challenge","outcome"],"skill":skill} for skill in skills[:count]]
        personalized.extend({"id":f"resume-project-{i+1}","topic":"Resume project","difficulty":difficulty,"prompt":f"Your resume describes this project: {project[:180]} Explain your specific contribution, a technical decision you made, and the result.","reference":"A strong response explains the project goal, the candidate's own contribution, a technical decision, and a measurable or concrete outcome.","concepts":["project","contribution","decision","result"],"skill":"Projects"} for i,project in enumerate((projects or [])[:count]))
        if personalized: return personalized[:count]
        pool = [q for q in pool if q["topic"] == "Projects"] or [q for q in BANK if q["topic"] == "Projects"]
    elif mode == "behavioral":
        pool = [q for q in pool if q["topic"] == "Behavioral"] or [q for q in BANK if q["topic"] == "Behavioral"]
    elif topic and topic != "All topics": pool = [q for q in pool if q["topic"].lower() == topic.lower()] or [q for q in BANK if q["topic"].lower() == topic.lower()] or pool
    random.shuffle(pool)
    return pool[:count]
